-- Vraies dates de mise en ligne YouTube de chaque film (relevées le 09/10/2026 sur la page watch, champ publishDate).
-- 1) ajoute la colonne published_at (date + heure exactes, utilisée pour les données structurées Google VideoObject.uploadDate) ;
-- 2) renseigne published_at ET corrige annee d'après la vraie date (heure UTC) pour 104 films.
-- Le film dépublié dont la vidéo YouTube a été supprimée (GLrOnXQk6t8) n'a pas de date et n'est pas modifié.
-- Répartition des années : 2020 : 1, 2021 : 6, 2023 : 5, 2024 : 5, 2025 : 16, 2026 : 71

ALTER TABLE films ADD COLUMN IF NOT EXISTS published_at TIMESTAMPTZ;

